/* kit_demo.c — demo sample kits made by this synthesizer (no third-party samples): every instrument of the
 * drums engine's three kits, hit once and recorded, becomes a WAV file NN_name.wav (NN: its MIDI note) in
 * OUT/synth_analog, OUT/synth_hybrid and OUT/synth_glitch, and each kit also as one file in the kit format
 * (OUT/NAME.oidk, dsp/core/kit.h: what the browser and the boards load). The sampler's patches play them.
 * Regenerated by every host build; deterministic, like the engine.
 *
 *   kit_demo OUT_DIR
 */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

#include "engines/drums.h"
#include "kitfile.h"
#include "synth.h"
#include "wav.h"

#define SR 48000
#define MAX_S 3 /* seconds rendered per hit */

int main(int argc, char **argv)
{
    if (argc != 2) {
        fprintf(stderr, "usage: kit_demo OUT_DIR\n");
        return 2;
    }
    static const char *kits[3] = {"synth_analog", "synth_hybrid", "synth_glitch"};
    static float L[SR * MAX_S], R[SR * MAX_S];
    static int16_t x[SR * MAX_S];
    mkdir(argv[1], 0755);
    for (int k = 0; k < 3; k++) {
        char dir[1024];
        snprintf(dir, sizeof dir, "%s/%s", argv[1], kits[k]);
        mkdir(dir, 0755);
        for (int i = 0; i < drums_engine.note_count; i++) {
            const engine_note_t *n = &drums_engine.notes[i];
            synth_t *s = synth_default();
            synth_init(s, (float)SR);
            synth_set_engine(s, SYNTH_ENGINE_DRUMS);
            synth_set_param(s, DRUMS_P_KIT, (float)k / 2.0f);
            const uint8_t on[3] = {0x90, n->note, 110}, off[3] = {0x80, n->note, 0};
            synth_midi(s, on, 3, 0);
            for (int p = 0; p < SR * MAX_S; p += 256) {
                if (p == 256 * 20)
                    synth_midi(s, off, 3, 0);
                synth_render(s, L + p, R + p, 256);
            }
            /* mono, trimmed where it falls 70 dB under its peak (then a 5 ms fade), peak at -1 dBFS */
            float peak = 0.0f;
            for (int p = 0; p < SR * MAX_S; p++)
                peak = fmaxf(peak, fabsf(0.5f * (L[p] + R[p])));
            int end = SR * MAX_S;
            while (end > 1 && fabsf(0.5f * (L[end - 1] + R[end - 1])) < peak * 3.16e-4f)
                end--;
            const int fade = SR / 200;
            end = end + fade < SR * MAX_S ? end + fade : SR * MAX_S;
            const float g = peak > 0.0f ? 0.891f / peak : 0.0f;
            for (int p = 0; p < end; p++) {
                const float f = p > end - fade ? (float)(end - p) / (float)fade : 1.0f;
                const float v = 0.5f * (L[p] + R[p]) * g * f * 32767.0f;
                x[p] = (int16_t)(v > 32767.0f ? 32767.0f : v < -32767.0f ? -32767.0f : v);
            }
            char path[1200], name[64];
            snprintf(name, sizeof name, "%s", n->name);
            for (char *c = name; *c; c++)
                if (*c == ' ')
                    *c = '_';
            snprintf(path, sizeof path, "%s/%02d_%s.wav", dir, n->note, name);
            if (wav_write_mono_i16(path, x, end, SR) != 0) {
                fprintf(stderr, "kit_demo: cannot write %s\n", path);
                return 1;
            }
        }
        size_t bytes;
        char err[512], path[1100];
        uint8_t *kit = kitfile_load_dir(dir, &bytes, err, sizeof err);
        snprintf(path, sizeof path, "%s/%s.oidk", argv[1], kits[k]);
        FILE *f = kit ? fopen(path, "wb") : NULL;
        if (!f || fwrite(kit, 1, bytes, f) != bytes || fclose(f) != 0) {
            fprintf(stderr, "kit_demo: %s: %s\n", path, kit ? "cannot write" : err);
            return 1;
        }
        free(kit);
    }
    return 0;
}
